import{d as g,C as t,o as c,c as m,j as a,a as r,E as n,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第六十九章","description":"由为客谦退读四无之象，依三宝与相惜之注辨轻敌和哀者胜。","frontmatter":{"title":"道德经第六十九章","description":"由为客谦退读四无之象，依三宝与相惜之注辨轻敌和哀者胜。","category":"guide","aliases":["道德经第六十九章","老子第六十九章","dao de jing chapter 69"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-69.md","filePath":"daoism/dao-de-jing/chapter-69.md","lastUpdated":1794189804000}'),u={name:"daoism/dao-de-jing/chapter-69.md"},k=g({...u,setup(p){const i=[{id:"guest-instead-of-initiator",label:"吾不敢为主而为客",showLabel:!0,sentences:[["用兵有言：吾不敢为",{text:"主",glossary:"zhu"},"而为",{text:"客",glossary:"ke"},"，不敢进寸而退尺。"]],note:["【白话】用兵有这样的话：我不敢做先发动的一方，宁愿做回应的一方；不敢前进一寸，宁愿退后一尺。语势着重不敢争先与宁可谦退。","【读法】主、客先按先发与应对分辨，不只是主客身份的字面。寸尺对举强化进退的选择，不直接当作现代战场的距离规则。","【读法】所据这句后未见独立逐句王注；下文的谦退哀慈、不敢为物先可帮助贯通全段，但不冒充此句独立原注。"]},{id:"acting-without-aggression",label:"是谓行无行",showLabel:!0,sentences:[["是谓",{text:"行",glossary:"xing"},"无",{text:"行",glossary:"hang"},"，",{text:"攘",glossary:"rang"},"无臂，",{text:"仍",glossary:"reng"},"无敌，执无兵。"]],note:["【白话】这叫作行进却像没有摆出可争的行阵，举臂却像无臂可振，迎敌却像没有敌手可争，执持却像无兵器可用。四个取象共同写出用兵而不逞强的姿态。","【王弼注择要】「行，谓行陈也。」又以「谦退哀慈，不敢为物先」解释这组句子，并说「言无有与之抗也」。","【读法】本页将第一个行作行动、行进，后一个行依王注作行阵，分别标音；不是宣称无需阵列、身体或兵器也能作战。仍取牵引、迎引义，本站保留仍，所据录文作扔，详见篇末。"]},{id:"the-danger-of-disdain",label:"祸莫大于轻敌",showLabel:!0,sentences:[["祸莫大于",{text:"轻敌",glossary:"qingdi"},"，"]],note:["【白话】祸患没有比轻率对敌、轻视敌手更大的了。这一句紧接谦退之意，转而警戒失去这种持守的危险。","【王弼注择要】「言吾哀慈谦退，非欲以取强无敌于天下也。」注特别说明，前面的谦退不是一套求强无敌的方法。","【读法】轻敌可以先按轻视敌手读；本章王注更把警戒放在求强无敌而失去哀慈谦退，不能只缩成对敌方实力估计不准。"]},{id:"almost-losing-the-treasures",label:"轻敌几丧吾宝",showLabel:!0,sentences:[[{text:"轻敌",glossary:"qingdi"},{text:"几",glossary:"ji"},{text:"丧",glossary:"sang"},"吾",{text:"宝",glossary:"bao"},"。"]],note:["【白话】轻敌几乎使我丧失所珍守的宝。依王注，这宝就是前文的三宝：慈、俭、不敢为天下先。","【王弼注择要】「宝，三宝也。故曰几亡吾宝。」注将此处的宝明确接回三宝，不只说一件贵重物品。","【读法】若把谦退当作更隐蔽的求强手段，便可能只剩下必欲胜人的目标；此时虽还保留退让的外形，所守的慈与不敢为先却已改变。"]},{id:"sorrow-and-mutual-care",label:"故抗兵相加，哀者胜矣",showLabel:!0,sentences:[["故",{text:"抗兵",glossary:"kangbing"},{text:"相加",glossary:"xiangjia"},"，",{text:"哀",glossary:"ai"},"者胜矣。"]],note:["【白话】所以，当两军举兵相接、相互对抗时，怀有哀悯之心的一方获胜。这是本章从哀慈谦退出发，对战胜所作的判断。","【王弼注择要】「抗，举也。加，当也。」又说「哀者必相惜」，把哀接到相互怜惜，而不只在悲伤或愤怒上说。","【读法】哀者胜保留经文的断言语气；现代导读应辨明它所重的怜惜生命与不得已，不把受伤、悲愤或复仇情绪本身说成必胜条件。"]}],s=[{id:"zhu",term:"主",sense:1},{id:"ke",term:"客",sense:1},{id:"xing",term:"行",sense:1},{id:"hang",term:"行",sense:2,pinyin:["háng"]},{id:"rang",term:"攘",sense:1},{id:"reng",term:"仍",sense:1},{id:"qingdi",term:"轻敌",sense:1},{id:"ji",term:"几",sense:1},{id:"sang",term:"丧",sense:1},{id:"bao",term:"宝",sense:2},{id:"kangbing",term:"抗兵",sense:1},{id:"xiangjia",term:"相加",sense:1},{id:"ai",term:"哀",sense:1}];return(x,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十九章",tabindex:"-1"},[r("道德经第六十九章 "),a("a",{class:"header-anchor",href:"#道德经第六十九章","aria-label":'Permalink to "道德经第六十九章"'},"​")],-1)),n(o,{title:"用兵之戒，为什么最后落在几丧吾宝",summary:"开头借用兵之言表明不敢先发、宁退不进，中间以行无行等取象写谦退。王弼尤其提醒：哀慈谦退并不是为了求强无敌，否则反会丢失三宝。结尾的哀者胜，要连相惜与不敢为先来读。",points:[{label:"先读",text:"主与客侧重先发与回应，进寸与退尺强化谦退的取向。"},{label:"再辨",text:"四无不是描述身体或器械真的消失；本站仍无敌与录文扔无敌分列说明。"},{label:"后看",text:"轻敌几丧吾宝回接第六十七章三宝，哀依王注相惜，不只作悲愤复仇解。"}],hint:"行无行本页读 xíng wú háng，后一个行为行阵；攘读 rǎng，仍读 réng，几读 jī，丧读 sàng。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:i,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"吾不敢为主而为客，不敢进寸而退尺。",tone:"不敢为先的用兵语言",guide:"从主客、寸尺的对照，看见全章谦退的起点。"},{text:"祸莫大于轻敌，轻敌几丧吾宝。",tone:"争强会改变所守",guide:"王注不以取强无敌为目的，吾宝明确回指三宝。"},{text:"故抗兵相加，哀者胜矣。",tone:"哀与相惜相连",guide:"承前面的哀慈谦退，不把哀只释为怒意或仇恨。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:s}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-行无行等四无-是在说什么消失了" tabindex="-1">象：行无行等四无，是在说什么消失了？ <a class="header-anchor" href="#象-行无行等四无-是在说什么消失了" aria-label="Permalink to &quot;象：行无行等四无，是在说什么消失了？&quot;">​</a></h3><p>本页依谦退哀慈的王注，把它们作为不逞强的取象来读。行阵、举臂、迎敌与执兵都仍在用兵语境里，不能据此推出一种让身体、兵器或现实危险消失的能力。</p><h3 id="理-为什么轻敌会连到丧失三宝" tabindex="-1">理：为什么轻敌会连到丧失三宝？ <a class="header-anchor" href="#理-为什么轻敌会连到丧失三宝" aria-label="Permalink to &quot;理：为什么轻敌会连到丧失三宝？&quot;">​</a></h3><p>王弼强调谦退不是为了求强无敌。若只把退让作为赢过天下的手段，就可能舍慈、舍俭、舍后而只求勇、广、先，正接第六十七章的反面警戒。</p><h3 id="用-今天怎样理解哀而不转成报复" tabindex="-1">用：今天怎样理解哀而不转成报复？ <a class="header-anchor" href="#用-今天怎样理解哀而不转成报复" aria-label="Permalink to &quot;用：今天怎样理解哀而不转成报复？&quot;">​</a></h3><p>可以先承认损伤、看见各方承受的代价，再明确需要停止的伤害、应承担的责任与可行的修复。相惜不要求忽略事实与边界，也不让悲痛直接成为不断扩大冲突的理由。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>检查目标是否只剩让对方败下去。</strong> 当解决分歧逐渐变成证明自己无敌，可以重新写下需要保全的人、资源与合作条件。这个提问来自三宝的章间关系，具体处理仍须看事实。</p><p><strong>把代价放回讨论里。</strong> 提出更强硬的行动前，说明谁会承担后果、哪些影响难以挽回、是否有更少伤害的处理方式。哀的现代启发，可以从认真计算这些人的处境开始。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我以为自己在谦退时，是否仍把求强无敌当作唯一目的？面对冲突，我最不愿丢失的三项持守是什么？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文、标点与别名沿本站保留，据卷四 007a 电子录文核对。本站作仍无敌，所据经注连排录文作扔无敌；不据该录文静默替换正文。</li><li>本站四句依行无行、攘无臂、仍无敌、执无兵排列。所据王注释句另以行、攘、执、扔复述，不以注中复述次序改排经文。</li><li>行无行的后一个行依行谓行陈也取行阵义，读 háng；第一个行本页取行进义，读 xíng。仍按汉典所列通扔、牵引义读 réng，不把现代扔的投掷义直接套入。字训参见<a href="https://www.zdic.net/hans/%E8%A1%8C" target="_blank" rel="noreferrer">汉典·行</a>、<a href="https://www.zdic.net/hans/%E4%BB%8D" target="_blank" rel="noreferrer">汉典·仍</a>。</li><li>吾宝据宝三宝也回指第六十七章；哀据哀者必相惜释读。所据行无行后另有彼逐不止字样，末注另有不趣利避害等连文，本页不擅猜校或扩作逐字定解。</li><li>古注节引转简体并加标点；仍／扔及难读注句的说明限所据电子录文，尚未逐字核对影印。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，007a</a>。</p>',15))])}}});export{_ as __pageData,k as default};
